\end{tabular}
\end{table}

\begin{table}[!htbp]
\centering\small
\caption{최종 Rényi 집계에서의 계층 가중치 (AD2 public, seed 0, Q95, CQ-on, AUPRO@0.05, \%). $\lambda=0$은 얕은 계층의 점수 기여만 제외한다. 굵은 값은 최고값이다.}
\label{tab:lambda_final}
\begin{tabular*}{\columnwidth}{@{\extracolsep{\fill}}lrr}
\toprule
$\lambda$ & 2-shot & 16-shot \\
\midrule
0 & 59.05 & 59.11 \\
0.0625 & 59.76 & 59.73 \\
0.125 (사용값) & \textbf{59.92} & 60.16 \\
